"""Adds support for collecting the snapshot on a classical bts
with sbts admin library. (taf.collectors.snapshot)
"""


class ClassicalGnbSnapshotCollectorConfigurator:
    """Class providing snapshot collection"""

    def add_snapshot(self, ne_log_name, ne_log_configuration):
        """Creates the collector for snapshot collection on a classical bts
        with the admin library

        :param str ne_log_name: The name of the collector
        :param dict ne_log_configuration: The optional configuration dictionary
        """

        webservice = self.tl_config_information_provider.get_web_service(node_id=self.ne_id)

        snapshot_collector_config = {
            'name': f'{ne_log_name}',
            'type': 'snapshot_sbts',
            'webservice': webservice,
            'coverage': 'Full',
            'force': 'False',
            'timeout': 480}

        self._collector_configuration_data.append(snapshot_collector_config)
        self._collector_configuration_data.add_mapping_entry(
            log_type='snapshot',
            network_element=f'{self.ne_type}_{self.ne_id}',
            collector_configuration=snapshot_collector_config)
